import json, os, sys
pkg = json.load(open("npmexport/package.json"))
exports = pkg.get("exports") or {}
def resolve(sub):
    if sub in exports:
        t = exports[sub]
        t = t if isinstance(t, str) else (t.get("import") or t.get("default"))
        return t
    for key, target in exports.items():
        if "*" in key:
            pre, post = key.split("*", 1)
            if sub.startswith(pre) and sub.endswith(post) and len(sub) >= len(pre) + len(post):
                mid = sub[len(pre):len(sub) - len(post)]
                t = target if isinstance(target, str) else (target.get("import") or target.get("default"))
                return t.replace("*", mid) if t else None
    return None
def exists(t):
    return t is not None and os.path.exists(os.path.join("npmexport", t))
legacy, root, length = resolve("./legacy"), resolve("."), resolve("./length")
print("legacy ->", legacy, exists(legacy), "| . ->", root, exists(root), "| ./length ->", length, exists(length))
sys.exit(0 if not exists(legacy) and exists(root) and exists(length) and not (legacy and "legacy" in legacy and "./legacy" in exports) else 1)
